<script setup lang="ts">import { computed, ref } from 'vue'; import { useRoute } from 'vue-router'; import { useAppStore } from '@/stores/app'; import TaskRow from '@/components/task/TaskRow.vue'; const app=useAppStore(); const route=useRoute(); const query=ref(''); const status=ref('All'); const rows=computed(()=>app.tasks.filter(t=>(route.query.assigned!=='me'||t.assignee?.id===app.currentUser.id)&&(status.value==='All'||t.status===status.value)&&t.title.toLowerCase().includes(query.value.toLowerCase())))</script>
<template><div class="page"><header class="page-header"><div><h1>{{route.query.assigned==='me'?'Your work':'All tasks'}}</h1><p>Filter, sort and manage tasks across the workspace.</p></div><button class="btn btn-primary">Create task</button></header><div class="toolbar"><input v-model="query" placeholder="Search tasks"/><select v-model="status"><option>All</option><option>Backlog</option><option>To do</option><option>In progress</option><option>Review</option><option>Done</option></select><select><option>All priorities</option><option>Highest</option><option>High</option><option>Medium</option><option>Low</option></select><select><option>Sort by updated</option><option>Sort by due date</option></select></div><section class="panel"><div class="task-list"><TaskRow v-for="task in rows" :key="task.id" :task="task"/></div></section></div></template>
